WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='LISTA_DE_PERSONAL' AND v.numero=1), d(t,o,n,sufijo,extras) AS (VALUES ('Personal que participó en el mantenimiento:',1,30,'',ARRAY['T. ESPECIALISTA 1:','T. ESPECIALISTA 2:','T. ESPECIALISTA 3:','SUPERVISOR 1:','SUPERVISOR 2:','SUPERVISOR 3:']),('Personal que participó en el mantenimiento Taller Electronica',2,13,'EL',ARRAY['T. ESPECIALISTA 1:','T. ESPECIALISTA 2:','T. ESPECIALISTA 3:','SUPERVISOR 1:','SUPERVISOR 2:','SUPERVISOR 3:']),('Personal que participó en el mantenimiento Taller Mecanica:',3,26,'M',ARRAY['T. ESPECIALISTA 1:','T. ESPECIALISTA 2:','T. ESPECIALISTA 3:','Responsable de Material rodante:','SUPERVISOR 1:','SUPERVISOR 1:']),('Personal que participó en el mantenimiento Taller Electrotecnia:',4,22,'E',ARRAY['T. ESPECIALISTA 1:','T. ESPECIALISTA 2:','Responsable de Material rodante:','SUPERVISOR 2:'])) INSERT INTO cartillas.secciones(version_id,titulo,orden) SELECT v.id,d.t,d.o FROM v CROSS JOIN d ON CONFLICT(version_id,orden) DO UPDATE SET titulo=EXCLUDED.titulo,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='LISTA_DE_PERSONAL' AND v.numero=1), s AS (SELECT id,titulo FROM cartillas.secciones WHERE version_id=(SELECT id FROM v)), d(t,c,n,sufijo,extras) AS (VALUES ('Personal que participó en el mantenimiento:','personal_general',30,'',ARRAY['T. ESPECIALISTA 1:','T. ESPECIALISTA 2:','T. ESPECIALISTA 3:','SUPERVISOR 1:','SUPERVISOR 2:','SUPERVISOR 3:']),('Personal que participó en el mantenimiento Taller Electronica','personal_electronica',13,'EL',ARRAY['T. ESPECIALISTA 1:','T. ESPECIALISTA 2:','T. ESPECIALISTA 3:','SUPERVISOR 1:','SUPERVISOR 2:','SUPERVISOR 3:']),('Personal que participó en el mantenimiento Taller Mecanica:','personal_mecanica',26,'M',ARRAY['T. ESPECIALISTA 1:','T. ESPECIALISTA 2:','T. ESPECIALISTA 3:','Responsable de Material rodante:','SUPERVISOR 1:','SUPERVISOR 1:']),('Personal que participó en el mantenimiento Taller Electrotecnia:','personal_electrotecnia',22,'E',ARRAY['T. ESPECIALISTA 1:','T. ESPECIALISTA 2:','Responsable de Material rodante:','SUPERVISOR 2:'])) INSERT INTO cartillas.campos(seccion_id,codigo,etiqueta,tipo,orden,configuracion) SELECT s.id,d.c,d.t,'tabla',1,jsonb_build_object('columnas',jsonb_build_array(jsonb_build_object('codigo','cargo','etiqueta','CARGO'),jsonb_build_object('codigo','firma','etiqueta','FIRMA','tipo','firma')),'filasIniciales',(SELECT jsonb_agg(jsonb_build_object('cargo',x)) FROM (SELECT 'TÉCNICO '||CASE WHEN g<=26 THEN chr(64+g) ELSE chr(64+(g-26))||chr(64+(g-26)) END||d.sufijo||':' x FROM generate_series(1,d.n)g UNION ALL SELECT unnest(d.extras))q)) FROM d JOIN s ON s.titulo=d.t ON CONFLICT(seccion_id,codigo) DO UPDATE SET configuracion=EXCLUDED.configuracion,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
